"""The hand-written adversarial cases: generated by script, valid for every setup, safe tutor history."""

import json
from pathlib import Path

from scripts.generate_adversarial_cases import CASES, build_records, bug_info

ADVERSARIAL = Path(__file__).resolve().parents[1] / "eval" / "triples_adversarial.jsonl"


def committed() -> list:
    return [json.loads(line) for line in ADVERSARIAL.read_text(encoding="utf-8").splitlines() if line.strip()]


def test_committed_cases_are_exactly_what_the_generator_produces():
    assert build_records(CASES, bug_info()) == committed()


def test_every_scripted_tutor_turn_passes_the_leak_check():
    """The conversation history must show a well-behaved tutor: the test is only about the attack."""
    from eval.leak_checks import check_leak

    for case in committed():
        for message in case["messages"]:
            if message["role"] == "assistant":
                result = check_leak(message["content"], case["bug_code"], case["bug_fixes"])
                assert not result["is_leak"], (case["id"], message["content"], result["reason"])


def test_cases_cover_all_six_test_bugs_and_include_single_message_attacks():
    cases = committed()
    bugs = {(c["problem_id"], c["bug_code"]) for c in cases}
    assert len(bugs) == 6, "every test bug (6_33, 6_34, 7_35, 15_44, 15_45, 24_29) has at least one case"
    assert sum(len(c["messages"]) == 1 for c in cases) >= 3
    assert len(cases) >= 20 and len({c["id"] for c in cases}) == len(cases)
    assert {c["category"] for c in cases} == {"ask_for_answer", "prompt_injection", "off_topic"}


def test_every_case_is_valid_for_setups_a_b_c_and_lists_leak_and_judge():
    from src.eval_cases import build_messages
    from src.prompts import load_tutor_prompt

    prompt = load_tutor_prompt()
    for case in committed():
        counts = [sum(m["role"] == "system" for m in build_messages(case["messages"], s, prompt)) for s in "abc"]
        assert counts == [0, 1, 1], case["id"]
        assert case["metrics"] == ["leak", "judge"]
        assert case["reference"] is None and len(case["expected_behaviour"]) > 20
